mapper.select:
SELECT  FROM book
 WHERE id=#{id,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND user_id=#{userId,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
 FOR UPDATE

SELECT  FROM book
 WHERE user_id=#{userId,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND source_hash=#{sourceHash,jdbcType=BINARY}

SELECT  FROM book
 WHERE user_id=#{userId,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND status IN ('IMPORTING','READY','FAILED','BROKEN')
AND (title LIKE #{q} ESCAPE '!' OR author LIKE #{q} ESCAPE '!')
AND (last_read_at < #{cursorTime,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
     OR (last_read_at = #{cursorTime,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
     AND id < #{cursorId,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}))
 ORDER BY last_read_at DESC, id DESC
 LIMIT #{limit}

mapper.update:
UPDATE book SET status='DELETING', updated_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
 WHERE id=#{id,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND user_id=#{userId,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND status IN ('READY','FAILED','BROKEN','IMPORTING')

UPDATE book SET status='IMPORTING', source_size=#{sourceSize}, original_filename=#{originalFilename},
                last_read_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler},
                updated_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
 WHERE id=#{id,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND status IN ('FAILED','BROKEN')

UPDATE book SET title=#{title}, author=#{author},
                updated_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
 WHERE id=#{id,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
